corrected_code:
const express = require('express');
const router = express.Router();
const { Connection, Client } = require('@temporalio/client');

router.post('/api/workflows/gdpr-purge', authenticateJwt, async (req, res) => {
  const { accountId } = req.body;

  if (req.user.accountId !== accountId && req.user.role !== 'COMPLIANCE_ADMIN') {
    return res.status(403).json({ error: 'Forbidden: you cannot initiate account purge for another account' });
  }

  const connection = await Connection.connect({ address: process.env.TEMPORAL_ADDRESS });
  const client = new Client({ connection });

  const handle = await client.workflow.start('PurgeAccountWorkflow', {
    taskQueue: 'compliance-queue',
    workflowId: `purge-${accountId}-${Date.now()}`,
    args: [{ targetAccountId: accountId, initiatedBy: req.user.id }]
  });

  return res.json({ workflowId: handle.workflowId, status: 'initiated' });
});
